style.css:
@-moz-document domain("roblox.com") {
/* MIDNIGHT NEKO - ROBLOX */

/* BACKGROUND IMAGE */
html,
body,
#app,
#container-main,
#wrap {
    background: transparent !important;
}

body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -1;
    pointer-events: none;

    background:
        linear-gradient(
            rgba(3, 8, 25, 0.15),
            rgba(3, 8, 25, 0.30)
        ),
        url("https://i.ibb.co/4Z3rfC30/0d656af756fae5bd5e0a165a17b01b32.jpg");

    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
}

/* PAGE PANELS */
#app,
#container-main,
#content,
#wrap,
main,
.section-content {
    background-color: transparent !important;
}

/* HEADER */
.navbar,
#navigation,
.navbar-fixed-top {
    background: rgba(5, 12, 35, 0.78) !important;
    backdrop-filter: blur(14px) !important;
}

/* SIDEBAR */
.left-col,
.sidebar,
#navigation-menu {
    background: rgba(5, 12, 35, 0.75) !important;
    backdrop-filter: blur(12px) !important;
}

/* GAME CARDS */
.game-card,
.game-card-container,
.list-item,
.avatar-card {
    background: rgba(8, 18, 45, 0.48) !important;
    border: 1px solid rgba(100, 160, 255, 0.2) !important;
    border-radius: 14px !important;
}

/* TEXT */
h1, h2, h3, h4,
.game-name,
.font-header {
    color: #f0f5ff !important;
}

/* SEARCH */
input,
.form-control {
    background: rgba(10, 20, 50, 0.85) !important;
    color: white !important;
    border: 1px solid rgba(100, 160, 255, 0.4) !important;
    border-radius: 12px !important;
}

/* SCROLLBAR */
::-webkit-scrollbar-thumb {
    background: #416da8 !important;
    border-radius: 10px !important;
}
}
